import time
import re
import logging
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.ue.connections.device_aliases import ue_pc
from moler.device import DeviceFactory


class BaseUe(object):
    def __init__(self, ue_id):
        self.id = ue_id
        self.serial_number = get_builtin_value("tl.ues[{}]".format(ue_id)).serial_number
        self.app_server_traffic_interface = get_builtin_value(
            "tl.ues[{}]".format(ue_id)).iperf_details.network_interface_address
        self.ue_pc = DeviceFactory.get_device(name=ue_pc.format(ue_id), initial_state="UNIX_REMOTE")
        self.iperf_launcher = None
        self.ip_address = None

    def _run_adb_cmd_on_ue(self, cmd):
        ue_adb_cmd = "adb -s {} {}".format(self.serial_number, cmd)
        self.ue_pc.get_cmd(cmd_name="run_script", cmd_params={'script_command': ue_adb_cmd})()


class AndroidUe(BaseUe):
    def __init__(self, ue_id, airplane_mode_coordinates):
        super(AndroidUe, self).__init__(ue_id=ue_id)
        self.airplane_mode_coordinates = airplane_mode_coordinates
        self.iperf_launcher = "adb -s {} shell {}". \
            format(self.serial_number,
                   "'run-as com.nokia.android.application '/data/user/0/com.nokia.android.application/{}''")

    def attach_ue(self, wait_for_ue=True):
        try:
            if not self._switch_airplane_mode_state_via_adb_tap(False):
                self._attach_ue_via_adb(wait_for_ue)
        except Exception as e:
            logging.info("Exception occurred during attach of {} UE: {}".format(self.serial_number, e))

    def detach_ue(self, wait_for_ue=True):
        try:
            if not self._switch_airplane_mode_state_via_adb_tap(True):
                self._detach_ue_via_adb(wait_for_ue)
        except Exception as e:
            logging.info("Exception occurred during detach of {} UE: {}".format(self.serial_number, e))

    def get_ue_ip(self):
        interfaces = ["scope global rmnet_data", "scope global bridge0", "scope global ccmni"]
        get_ip_cmd = self.ue_pc.get_cmd(cmd_name="echo", cmd_params={
            'text': "| adb -s {} shell 'ip a'".format(self.serial_number),
            'text_in_quotation': False})
        for line in get_ip_cmd()["RESULT"]:
            if any(interface in line for interface in interfaces):
                self.ip_address = re.search(r"inet\s+(\d+\.\d+\.\d+\.\d+)", line).group(1)
                return self.ip_address
        else:
            return None

    def _create_data_transfer_connections(self, direction):
        self.ue_pc_iperf = DeviceFactory.get_cloned_device("UE{}_PC".format(self.id),
                                                           "UE{}_PC_{}".format(self.id, direction),
                                                           initial_state="UNIX_REMOTE")
        self.ue_app_server = DeviceFactory.get_cloned_device("APP_SERVER{}".format(self.id),
                                                             "APP_SERVER{}_{}".format(self.id, direction),
                                                             initial_state="UNIX_REMOTE")

    def _switch_airplane_mode_state_via_adb_tap(self, enabled):
        switch_max_retry = 3
        for retry_index in range(switch_max_retry):
            self._run_adb_cmd_on_ue("shell 'input keyevent 82;input keyevent 66'")
            self._run_adb_cmd_on_ue("shell 'am start -a android.settings.AIRPLANE_MODE_SETTINGS;sleep 2'")
            self._run_adb_cmd_on_ue(
                "shell 'input tap {} {};svc data enable'".format(self.airplane_mode_coordinates["x"],
                                                                 self.airplane_mode_coordinates["y"]))
            time.sleep(5)
            if enabled and not self.get_ue_ip():
                logging.info("Airplane mode switched to state: enabled={}".format(str(enabled)))
                return True
            elif not enabled and self.get_ue_ip():
                logging.info("Airplane mode switched to state: enabled={}".format(str(enabled)))
                return True
            else:
                continue
        else:
            logging.error("Cannot change airplane mode to enabled={} state via adb tap")
            return False

    def _attach_ue_via_adb(self, wait_for_ue):
        self._run_adb_cmd_on_ue("shell 'settings put global airplane_mode_on 0;svc data enable'")
        self._run_adb_cmd_on_ue("reboot")
        time.sleep(60) if wait_for_ue else time.sleep(1)

    def _detach_ue_via_adb(self, wait_for_ue):
        self._run_adb_cmd_on_ue("shell 'settings put global airplane_mode_on 1;svc data enable'")
        self._run_adb_cmd_on_ue("reboot")
        time.sleep(60) if wait_for_ue else time.sleep(1)

    def _run_adb_cmd_on_ue(self, cmd):
        ue_adb_cmd = "adb -s {} {}".format(self.serial_number, cmd)
        self.ue_pc.get_cmd(cmd_name="run_script", cmd_params={'script_command': ue_adb_cmd})()


class AtCmdUe(BaseUe):
    def __init__(self, ue_id):
        super(AtCmdUe, self).__init__(ue_id=ue_id)
        self.iperf_launcher = "c:/iperf/{}"

    def attach_ue(self, wait_for_ue=True):
        try:
            if not self._attach_ue_via_at_cmd():
                self._run_adb_cmd_on_ue("adb -s {} shell 'at_cmd at+cfun=1'")
                self._run_adb_cmd_on_ue("reboot")
                time.sleep(60) if wait_for_ue else time.sleep(1)
        except Exception as e:
            logging.info("Exception occurred during attach of {} UE: {}".format(self.serial_number, e))

    def detach_ue(self, wait_for_ue=True):
        try:
            self._detach_ue_via_at_cmd()
            time.sleep(5) if wait_for_ue else time.sleep(1)
        except Exception as e:
            logging.info("Exception occurred during detach of {} UE: {}".format(self.serial_number, e))

    def get_ue_ip(self):
        self.ip_address = None
        get_ip_cmd = self.ue_pc.get_cmd(cmd_name="echo", cmd_params={
            'text': "| ipconfig", "text_in_quotation": False})
        for line in get_ip_cmd()["RESULT"]:
            ip_regex = re.search(r"^\s+IPv4 Address. . . . . . . . . . . :\s+(?P<IP>\d+\.\d+\.\d+\.\d+)", line)
            if ip_regex:
                self.ip_address = ip_regex.group("IP")
            if self.ip_address and "255.255.255.2" in line:
                return self.ip_address
            elif self.ip_address and "Subnet Mask" in line:
                self.ip_address = None
        else:
            return None

    def _attach_ue_via_at_cmd(self):
        at_cmd_attach_max_retries = 5
        for retry_index in range(at_cmd_attach_max_retries):
            self._run_adb_cmd_on_ue("adb -s {} shell 'at_cmd at+cfun=1'")
            time.sleep(10)
            if self.get_ue_ip():
                logging.info("UE attached properly via AT cmd")
                return True
            else:
                continue
        else:
            logging.error("UE cannot be properly attached")
            return False

    def _detach_ue_via_at_cmd(self):
        self._run_adb_cmd_on_ue("adb -s {} shell 'at_cmd at+cfun=0'")


class IphoneUe(BaseUe):
    def __init__(self, ue_id):
        super(IphoneUe, self).__init__(ue_id=ue_id)

    def attach_ue(self):
        raise NotImplementedError

    def detach_ue(self):
        raise NotImplementedError

    def get_ue_ip(self):
        raise NotImplementedError
